    async void TrailLedgerSmoke()=>await TryRuntime(async()=>
    {
        var output=System.IO.Path.GetFullPath(".artifacts/trail-ledger-desktop");System.IO.Directory.CreateDirectory(output);var checks=new List<string>();
        await RunTrailLedgerUiSmoke(output,(passed,label)=>{if(!passed)throw new InvalidOperationException("UI check failed: "+label);checks.Add(label);});
        System.IO.File.WriteAllText(System.IO.Path.Combine(output,"ui-checks.json"),System.Text.Json.JsonSerializer.Serialize(new{checks},BehaviorDocument.JsonOptions));Application.Current.Shutdown(0);
    });
    async Task RunTrailLedgerUiSmoke(string output,Action<bool,string> check)
    {
        var previous=Snapshot();var file=selectedEntity!.SourceFile;var supplied=System.IO.File.ReadAllText(file);var source="using TKR.WorldServer.logic.behaviors;namespace TKR.WorldServer.logic{public partial class BehaviorDb{private _ StudioDesktopTrail=()=>Behav().Init(\"Cave Pirate Brawler\",new State(\"trail\"));}}";
        ApplyProject(previous with{Source=source,Identities=[],SourceDrafts=[],SelectedSourceFile=null,LockedNodes=[],CollapsedNodes=[],Layout=[],AdditionalSources=[],Player=previous.Player with{Invulnerable=true,StartX=70.5,StartY=64.5},Arena=new()},null);WorkspaceTabs.SelectedIndex=1;var phase=EncounterRoot;SelectNode(phase.Id);
        BeginNativeCreation(adapter!.Primitives.Single(p=>p.Name=="TrailLedger"));check(constructorInputs["shardIndex"].Text=="0"&&createNativeButton!.IsEnabled,"Native trail creation seeds an actual moving owner XML projectile");constructorInputs["shardCount"].Text="4";constructorInputs["fuseMs"].Text="300";constructorInputs["startupMs"].Text="0";constructorInputs["intervalMs"].Text="100";constructorInputs["boundsRadius"].Text="5";constructorInputs["penaltyFuseMs"].Text="400";createNativeButton!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var ledger=selectedNode!;
        check(ledger.Kind=="TrailLedger"&&trailPanel!=null&&trailSummary!.Text.Contains("penalty fuse 400"),"Actual native Add selects the spawn-bound penalty preview");trailPanel!.IsExpanded=true;trailAim!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(adapter.ReadTrailLedger(document,document.Find(ledger.Id))!.Flags["interestAimed"],"Actual interest control commits the native aimed-fan option");Undo(this,new());check(!adapter.ReadTrailLedger(document,document.Find(ledger.Id))!.Flags["interestAimed"],"One editor Undo restores uniform interest geometry");Redo(this,new());check(adapter.ReadTrailLedger(document,document.Find(ledger.Id))!.Flags["interestAimed"],"One editor Redo retains the source option");
        document.LockedNodes.Add(ledger.Id);SelectNode(ledger.Id);check(trailAim?.IsEnabled==false,"Trail region locks disable native interest edits");document.LockedNodes.Clear();SelectNode(ledger.Id);projectilePicker!.IsExpanded=true;check(projectileChoices!.Items.OfType<ListBoxItem>().Any(i=>i.Tag is EnemyProjectile),"Trail projectile choices come from compatible moving owner XML");
        var path=System.IO.Path.Combine(output,"trail-ledger.rbs");var identities=document.Identities;BehaviorDocument.Save(path,Snapshot());ApplyProject(BehaviorDocument.Load(path),path);check(document.Identities.SequenceEqual(identities),"Native trail fields and identities survive save/reopen");check(await StartSessionAsync(),"Play starts the original native trail engine");running=false;await session!.AdvanceAsync(new(),100);UpdateSession();check(session.Effects.Any(e=>e.Kind==22&&e.DurationMs==400&&e.Y2==0),"Native Play emits the penalty glyph at the observed target position");await session.AdvanceAsync(new(),400);UpdateSession();check(session.Shots.Any(s=>s.Count==4&&s.Index==0),"Native delayed burst uses actual XML shard count and index");Stop(this,new());WorkspaceTabs.SelectedIndex=1;SelectNode(ledger.Id);trailPanel!.IsExpanded=true;UpdateLayout();CaptureView(this,System.IO.Path.Combine(output,"trail-ledger-editor.png"));
        SelectNode(phase.Id);BeginNativeCreation(adapter.Primitives.Single(p=>p.Name=="TrailRecount"));constructorInputs["windowMs"].Text="500";constructorInputs["spacing"].Text="1";constructorInputs["minFuseMs"].Text="300";constructorInputs["maxFuseMs"].Text="600";constructorInputs["startupMs"].Text="500";constructorInputs["intervalMs"].Text="1000";createNativeButton!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var recount=selectedNode!;
        check(recount.Kind=="TrailRecount"&&recountAge!=null&&trailSummary!.Text.Contains("Native resample"),"Native recount Add exposes an original-helper movement illustration");var revision=document.Revision;recountAge!.Value=500;check(document.Revision==revision,"Recount fuse preview changes presentation without source mutation");check(await StartSessionAsync(),"Combined ledger/recount source uses native Play");running=false;await session!.AdvanceAsync(new(1,0),600);UpdateSession();check(session.Effects.Any(e=>e.Kind==22&&e.DurationMs is >=300 and <=600),"Actual observed movement produces native history marks");Stop(this,new());WorkspaceTabs.SelectedIndex=1;SelectNode(recount.Id);trailPanel!.IsExpanded=true;UpdateLayout();CaptureView(this,System.IO.Path.Combine(output,"trail-recount-editor.png"));
        check(System.IO.File.ReadAllText(file)==supplied,"Trail controls and native history playback preserve supplied source");ApplyProject(previous,null);WorkspaceTabs.SelectedIndex=0;
    }
